const rows = $input.all().map(i => i.json);
const freqRow = rows.find(r => r.key === 'frecuencia_guias_dias');
const lastRow = rows.find(r => r.key === 'ultima_ejecucion_guias');
const freqDays = parseInt(freqRow && freqRow.value || '2', 10) || 2;
const todayUTC = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate()));
const lastValue = lastRow && lastRow.value;
if (lastValue) {
  const lastRun = new Date(lastValue + 'T00:00:00Z');
  const diffDays = Math.floor((todayUTC - lastRun) / 86400000);
  if (diffDays < freqDays) {
    return [];
  }
}
return [{ json: { todayISO: todayUTC.toISOString().slice(0, 10) } }];

const row = $json;
const relevancia = (row.relevancia === null || row.relevancia === undefined) ? null : row.relevancia;
const lines = [];
lines.push(row.reminder ? '🔁 [WattFigures] Recordatorio: esta idea sigue pendiente de respuesta' : '💡 [WattFigures] Nueva idea de guía');
lines.push('');
lines.push('Tema: ' + row.topic);
lines.push('Keyword: ' + row.keyword);
lines.push('Categoria: ' + row.category);
if (relevancia !== null) lines.push('📈 Relevancia: ' + relevancia + '/100');
if (row.notes) lines.push('Notas: ' + row.notes);
lines.push('');
lines.push('Se generara en EN+ES, se validara automaticamente y si TODO pasa se publicara sola en wattfigures.com, sin mas confirmacion.');
const text = lines.join('\n');
return [{ json: { rowId: row.id, text } }];

const items = $input.all().filter(i => i.json && i.json.id !== undefined);
if (items.length === 0) {
  return [{ json: { noTopic: true } }];
}
return [{ json: { ...items[0].json, noTopic: false } }];

const trig = $('Telegram callback (WattFigures)').first().json || {};
const cb = trig.callback_query || {};
const data = cb.data ? String(cb.data) : '';
const queryId = cb.id || '';
const m = data.match(/^wfguia:(go|skip):(\d+)$/);
const action = m ? m[1] : null;
const rowId = m ? parseInt(m[2], 10) : null;
return [{ json: { action, rowId, queryId, data } }];

