function validateDraft(d) {
  const errors = [];
  if (!d.title || d.title.length < 30 || d.title.length > 70) errors.push('title length ' + (d.title ? d.title.length : 0) + ', expected 30-70');
  if (!d.description || d.description.length < 100 || d.description.length > 175) errors.push('description length ' + (d.description ? d.description.length : 0) + ', expected 100-175');
  if (!d.slug || !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(d.slug)) errors.push('slug missing or not kebab-case');
  if (!Array.isArray(d.faq_items) || d.faq_items.length < 3 || d.faq_items.length > 4) errors.push('faq_items count ' + (d.faq_items ? d.faq_items.length : 0) + ', expected 3-4');
  const body = d.body_html || '';
  const words = body.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  if (words.length < 1000) errors.push('body ' + words.length + ' words, expected >= 1000');
  if (/<h1[ >]/.test(body)) errors.push('body contains h1');
  const h2Count = (body.match(/<h2[ >]/g) || []).length;
  if (h2Count < 2) errors.push('body has ' + h2Count + ' h2, expected >= 2');
  if (/<h[4-6][ >]/.test(body)) errors.push('body uses h4/h5/h6');
  const firstH2 = body.search(/<h2[ >]/);
  const firstH3 = body.search(/<h3[ >]/);
  if (firstH3 !== -1 && (firstH2 === -1 || firstH3 < firstH2)) errors.push('h3 before h2');
  const hasList = /<(ul|ol)[ >]/.test(body);
  const hasTable = /<table[ >]/.test(body);
  if (!hasList && !hasTable) errors.push('no list or table');
  const allowed = ['h2','h3','p','ul','ol','li','table','thead','tbody','tr','th','td','strong','em','a','code'];
  const tagsUsed = [...body.matchAll(/<\/?([a-z0-9]+)(?:\s|>|\/)/gi)].map(m => m[1].toLowerCase());
  const bad = [...new Set(tagsUsed)].filter(t => !allowed.includes(t));
  if (bad.length) errors.push('disallowed tags: ' + bad.join(','));
  const hrefs = [...body.matchAll(/<a[^>]*href="([^"]*)"/g)].map(m => m[1]);
  for (const h of hrefs) { if (h === '#' || h.startsWith('javascript:')) errors.push('dead link: ' + h); }
  if (/\\"/.test(body)) errors.push('body contains backslash-escaped quotes (emit plain HTML, the JSON layer escapes)');
  const VALID_CALC = ['air-conditioning','electricity-cost','ev-charging','heat-pump-vs-gas','laundry-cost','led-vs-halogen','solar-payback','standby-power'];
  const VALID_GUIDES = ['how-to-cut-standby-power','time-of-use-tariffs-explained','understanding-your-electricity-bill','vampire-device-audit-checklist','heat-pump-vs-gas-boiler-running-cost'];
  const internal = [...body.matchAll(/href="(\/(?:es\/)?(?:calculators|guides)\/[^"]*)"/g)].map(m => m[1]);
  for (const u of internal) {
    const parts = u.replace(/^\/(es\/)?/, '').replace(/\/$/, '').split('/');
    const sec = parts[0], sl = parts[1];
    if (!sl) continue;
    const ok = sec === 'calculators' ? VALID_CALC.includes(sl) : VALID_GUIDES.includes(sl);
    if (!ok) errors.push('internal link to non-existent page: ' + u);
  }
  const badChars = ['Ã©','Ã³','Ã±','Ã­','Ã¡','Ãº','â€','Â¿','Â¡','�'];
  for (const b of badChars) { if (body.includes(b) || (d.title || '').includes(b)) { errors.push('mojibake detected'); break; } }
  return { valid: errors.length === 0, errors };
}

const draft = $json.output || $json;
const result = validateDraft(draft);
const topic = $('Leer tema por id').first().json;
return [{ json: { ...draft, category: topic.category, keyword: topic.keyword, _valid: result.valid, _errors: result.errors } }];

