const prev = $('Adjuntar relacionados ES').first().json;
const en = prev.en;
const es = prev.es;
const slug = en.slug;
const todayISO = new Date().toISOString().slice(0, 10);
const canonicalEN = 'https://wattfigures.com/guides/' + slug + '/';
const canonicalES = 'https://wattfigures.com/es/guides/' + slug + '/';
const ogImage = 'https://wattfigures.com/assets/img/og-default.png';

function mk(d, canonical) {
  return {
    title: d.title + ' | WattFigures',
    description: d.description,
    keywords: d.keywords,
    headline: d.headline,
    breadcrumb_name: d.breadcrumb_name,
    lead: d.lead || d.description,
    body_html: d.body_html,
    faq_items: d.faq_items,
    canonical_url: canonical,
    date_published: todayISO,
    related: []
  };
}

const draft = {
  slug: slug,
  category: prev.category,
  og_image: ogImage,
  en: Object.assign(mk(en, canonicalEN), { hreflang_es_url: canonicalES, related: prev.related_en || [] }),
  es: Object.assign(mk(es, canonicalES), { hreflang_en_url: canonicalEN, related: prev.related_es || [] })
};
return [{ json: { draft: draft } }];

const draft = $('Ensamblar borrador').first().json.draft;
const decode = (r) => Buffer.from(r.content, 'base64').toString('utf-8');
const tplEn = decode($('Obtener plantilla EN (GitHub)').first().json);
const tplEs = decode($('Obtener plantilla ES (GitHub)').first().json);

function escHtml(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function faqJson(items) {
  return JSON.stringify((items || []).map(f => ({ '@type': 'Question', name: f.question, acceptedAnswer: { '@type': 'Answer', text: f.answer } })));
}
function faqVisible(items) {
  return (items || []).map(f => '<details class="faq-item"><summary>' + escHtml(f.question) + '</summary><p>' + escHtml(f.answer) + '</p></details>').join('\n      ');
}
function relatedItems(rel) {
  return (rel || []).slice(0, 4).map(r => '        <li><a class="ul-link" href="' + r.url + '">' + escHtml(r.title) + '</a></li>').join('\n');
}

function fill(tpl, lang) {
  const d = lang === 'en' ? draft.en : draft.es;
  const enc = encodeURIComponent;
  const map = {
    TITLE: escHtml(d.title), DESCRIPTION: escHtml(d.description), KEYWORDS: escHtml(d.keywords),
    CANONICAL_URL: d.canonical_url,
    HREFLANG_ES_URL: lang === 'en' ? d.hreflang_es_url : d.canonical_url,
    HREFLANG_EN_URL: lang === 'es' ? d.hreflang_en_url : d.canonical_url,
    OG_IMAGE: draft.og_image,
    HEADLINE: escHtml(d.headline),
    LEAD: escHtml(d.lead),
    DATE_PUBLISHED: d.date_published,
    BREADCRUMB_NAME: escHtml(d.breadcrumb_name),
    BODY_HTML: d.body_html,
    FAQ_JSONLD: faqJson(d.faq_items),
    FAQ_VISIBLE: '      ' + faqVisible(d.faq_items),
    RELATED_ITEMS: relatedItems(d.related),
    CANONICAL_URL_ENC: enc(d.canonical_url),
    OG_IMAGE_ENC: enc(draft.og_image),
    HEADLINE_ENC: enc(d.headline)
  };
  let out = tpl;
  for (const k of Object.keys(map)) {
    out = out.split('{{' + k + '}}').join(String(map[k] == null ? '' : map[k]));
  }
  const leftover = out.match(/\{\{[A-Z0-9_]+\}\}/);
  if (leftover) throw new Error('Placeholder sin rellenar (' + lang + '): ' + leftover[0]);
  return out;
}

return [{ json: { draft: draft, htmlEn: fill(tplEn, 'en'), htmlEs: fill(tplEs, 'es') } }];

