const d = $('Rellenar plantillas (Code)').first().json.draft;
function decode(raw) { return Buffer.from(raw.content, 'base64').toString('utf-8'); }
function escHtml(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function insertCardAndList(html, opts) {
  const marker = '<!-- CARDS:START -->';
  if (!html.includes(marker)) throw new Error('Marcador CARDS:START no encontrado en ' + opts.pagePath);
  const card = '<a class="card" href="' + d.slug + '/"><div class="card-body"><div class="chip">' + opts.chip + '</div><h3 class="font-display">' + escHtml(opts.h3) + '</h3><p>' + escHtml(opts.p) + '</p></div></a>';
  let out = html.replace(marker, marker + '\n' + card);
  const anchor = '"itemListElement": [';
  const anchorIdx = out.indexOf(anchor);
  if (anchorIdx === -1) throw new Error('itemListElement no encontrado en ' + opts.pagePath);
  const closeIdx = out.indexOf(']', anchorIdx);
  if (closeIdx === -1) throw new Error('Cierre de itemListElement no encontrado en ' + opts.pagePath);
  const segment = out.slice(anchorIdx, closeIdx);
  const positions = [...segment.matchAll(/"position":\s*(\d+)/g)].map(m => parseInt(m[1], 10));
  const nextPos = positions.length ? Math.max(...positions) + 1 : 1;
  const escJ = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  const entry = (positions.length ? ',' : '') + '\n      { "@type": "ListItem", "position": ' + nextPos + ', "url": "' + opts.canonical + '", "name": "' + escJ(opts.name) + '" }\n    ';
  out = out.slice(0, closeIdx) + entry + out.slice(closeIdx);
  return out;
}
const enIdx = insertCardAndList(decode($('Obtener indice EN (GitHub)').first().json), { pagePath: 'guides/index.html', chip: 'Saving Guides', h3: d.en.headline, p: d.en.description, canonical: d.en.canonical_url, name: d.en.headline });
const esIdx = insertCardAndList(decode($('Obtener indice ES (GitHub)').first().json), { pagePath: 'es/guides/index.html', chip: 'Guías de ahorro', h3: d.es.headline, p: d.es.description, canonical: d.es.canonical_url, name: d.es.headline });
return [
  { json: { path: 'guides/index.html', fileContent: enIdx, message: 'feat(guides): tarjeta ' + d.slug + ' [n8n]' } },
  { json: { path: 'es/guides/index.html', fileContent: esIdx, message: 'feat(guides): tarjeta es/' + d.slug + ' [n8n]' } }
];

